async function peerState(instance){const result=await instance.browser.executeAsync((done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionState.ts")]).then(async([{mockAdapter},{connectedStateFor}])=>{const s=await mockAdapter.getSnapshot();const st=connectedStateFor(mockAdapter);const r=s.resolution;done({role:s.session.role,connectionState:s.connectionState,mode:s.sessionMode,currentActorId:s.scene.currentActorId,cursor:st.replica?.cursor??st.ledger?.cursor??null,pendingRemote:Boolean(st.pendingRemoteAction),compatibilityMessage:s.session.compatibilityMessage,activeCharacterId:s.activeCharacter.id,slots:(s.scene.spellcastingByActor?.[s.activeCharacter.id]?.slots??[]).map((l)=>({level:l.level,current:l.current,max:l.max})),announcement:document.querySelector(".session-resolution-announcement")?.textContent??"",resolution:r?{id:r.id,stage:r.stage,actorId:r.actorId,actionName:r.actionName,targetIds:r.targetIds,dice:r.authoritativeDice,compact:r.compact,finalOutcome:r.finalOutcome,attackOutcome:r.attackOutcome,attackTotal:r.attackTotal,rollTotal:r.rollTotal,critical:r.critical,canAdvance:r.canAdvance,stateChanges:r.stateChanges,damageComponents:(r.damageComponents??[]).length,checkTarget:r.checkTarget,checkOutcome:r.checkOutcome,interrupt:r.interrupt?{id:r.interrupt.id,responderId:r.interrupt.responderId,optionName:r.interrupt.optionName,trigger:r.interrupt.trigger}:null,concentrationSave:r.concentrationSave?{targetId:r.concentrationSave.targetId,natural:r.concentrationSave.natural??null,total:r.concentrationSave.total??null,dc:r.concentrationSave.dc??null,outcome:r.concentrationSave.outcome??null}:null,saves:(r.saveResults??[]).map((x)=>({targetId:x.targetId,targetName:x.targetName,total:x.total,dc:x.dc,outcome:x.outcome}))}:null,items:s.activeCharacter.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity,equipped:i.equipped})),inventory:(()=>{const inv=s.sessionCharacterInventories?.[s.activeCharacter.id];return inv?{revision:inv.revision,goldGp:inv.goldGp,items:inv.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity}))}:null;})(),activity:s.activity.slice(0,60).map((e)=>({id:e.id,actor:e.actor,title:e.title,summary:e.summary,stateChanges:e.stateChanges,detail:e.detail})),entities:s.scene.entities.map((e)=>({id:e.id,name:e.name,hp:e.hp,maxHp:e.maxHp,kind:e.kind,initiative:e.initiative??null,side:e.side,status:[...(e.status??[])]})),resources:(s.activeCharacter.resources??[]).map((x)=>({id:x.id,label:x.label,current:x.current,max:x.max})),hasCanvas:Boolean(document.querySelector("canvas"))});}).catch((error)=>done({error:String(error?.stack??error)}));});assert.ok(!result.error,result.error);return result;}
async function refreshShell(instance){await instance.browser.executeAsync((done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{await publishConnectedSnapshot(mockAdapter);done({ok:true});}).catch((error)=>done({error:String(error?.stack??error)}));});}
async function actions(instance,actorId){return instance.browser.executeAsync((actorId,done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();done((s.scene.actionsByActor[actorId]??[]).map((a)=>({id:a.id,name:a.name,available:a.available,disabledReason:a.disabledReason,target:a.target,eligibleTargetIds:a.eligibleTargetIds,resolutionKind:a.resolutionKind,economy:a.economy,spellId:a.spellCast?.spellId??null,readyActionRole:a.readyActionRole??null,maxTargets:a.maxTargets??null})));}).catch((error)=>done({error:String(error?.stack??error)}));},actorId);}
async function findAction(instance,actorId,predicate,label){const list=await actions(instance,actorId);assert.ok(!list.error,list.error);const found=list.find(predicate);assert.ok(found,`${instance.label}: action ${label} not projected for ${actorId}; have ${list.map((a)=>a.name).join("|")}`);return found;}
async function hostCall(host,body,args){const result=await host.browser.executeAsync(new Function("args","done",`Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const out=await (async()=>{${body}})();await publishConnectedSnapshot(mockAdapter);done({ok:true,out});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));`),args??{});assert.equal(result.ok,true,result.error);return result.out;}
const seenResolutionIds=new Set();
// Walks the authoritative Initiative to the actor's next fresh turn. If the actor is already current its turn economy may be spent, so the Host ends that turn first and cycles the order once.
async function peerCall(instance,body,args){const result=await instance.browser.executeAsync(new Function("args","done",`Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const out=await (async()=>{${body}})();await publishConnectedSnapshot(mockAdapter);done({ok:true,out});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));`),args??{});assert.equal(result.ok,true,`${instance.label}: ${result.error}`);return result.out;}
// A created Cleric holds mace + shield; stowing the shield through the production inventory API frees the hand that somatic-only spells (Sacred Flame, Guiding Bolt, Cure Wounds) need.
async function stowShield(instance){return peerCall(instance,`const s=await mockAdapter.getSnapshot();const shield=s.activeCharacter.items.find((i)=>i.definitionId==="dnd.srd521.item.shield"&&i.equipped);if(!shield)return {stowed:false,items:s.activeCharacter.items.map((i)=>i.name+":"+(i.equipped?"E":"-")+(i.wielded?"W":"-"))};const after=await mockAdapter.toggleItemEquipped(shield.id);return {stowed:true,wielded:after.activeCharacter.items.filter((i)=>i.wielded).map((i)=>i.name+":"+i.wieldSlot)};`);}
async function paritySnapshot(instance,actorId){const result=await instance.browser.executeAsync((actorId,done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();const e=s.scene.entities.find((x)=>x.id===actorId);const norm=(a)=>({id:a.id,name:a.name,category:a.category,economy:a.economy,target:a.target,available:a.available,resolutionKind:a.resolutionKind,eligibleTargetIds:[...(a.eligibleTargetIds??[])].sort(),maxTargets:a.maxTargets??null,spellId:a.spellCast?.spellId??null});const inv=s.sessionCharacterInventories?.[actorId];done({roster:s.scene.entities.map((x)=>({id:x.id,name:x.name,side:x.side,kind:x.kind})).sort((a,b)=>a.id<b.id?-1:1),actor:e?{id:e.id,name:e.name,hp:e.hp,maxHp:e.maxHp,tempHp:e.tempHp,ac:e.ac,status:[...e.status].sort(),initiative:e.initiative}:null,economy:s.scene.economyByActor[actorId]??null,currentActorId:s.scene.currentActorId,mode:s.sessionMode,actions:(s.scene.actionsByActor[actorId]??[]).map(norm).sort((a,b)=>a.id<b.id?-1:1),inventory:inv?{goldGp:inv.goldGp,items:inv.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity,equipped:i.equipped,wielded:i.wielded??false,wieldSlot:i.wieldSlot??null})).sort((a,b)=>a.id<b.id?-1:1)}:null});}).catch((error)=>done({error:String(error?.stack??error)}));},actorId);assert.ok(!result.error,result.error);return result;}
function actionParityDiff(hostActions,clientActions,{compareAvailability=true}={}){const byId=new Map(clientActions.map((a)=>[a.id,a]));const diffs=[];for(const h of hostActions){const c=byId.get(h.id);if(!c){diffs.push(`missing on client: ${h.id}`);continue;}for(const key of ["name","category","economy","target","resolutionKind","maxTargets","spellId",...(compareAvailability?["available"]:[])]){if(JSON.stringify(h[key])!==JSON.stringify(c[key]))diffs.push(`${h.id}.${key}: host=${JSON.stringify(h[key])} client=${JSON.stringify(c[key])}`);}if(JSON.stringify(h.eligibleTargetIds)!==JSON.stringify(c.eligibleTargetIds))diffs.push(`${h.id}.eligibleTargetIds: host=${JSON.stringify(h.eligibleTargetIds)} client=${JSON.stringify(c.eligibleTargetIds)}`);}for(const c of clientActions)if(!hostActions.some((h)=>h.id===c.id))diffs.push(`missing on host: ${c.id}`);return diffs;}
async function expectUiParity(host,client,actorId,label){const h=await paritySnapshot(host,actorId);const c=await paritySnapshot(client,actorId);assert.deepEqual(c.roster,h.roster,`${label}: roster diverges`);assert.deepEqual(c.actor,h.actor,`${label}: Actor projection diverges`);assert.deepEqual(c.economy,h.economy,`${label}: turn economy diverges`);assert.equal(c.currentActorId,h.currentActorId,`${label}: current Actor diverges`);const ownTurn=h.currentActorId===actorId;const diffs=actionParityDiff(h.actions,c.actions,{compareAvailability:ownTurn});assert.deepEqual(diffs,[],`${label}: action bar diverges: ${diffs.slice(0,12).join(" | ")}`);if(h.inventory&&c.inventory){assert.equal(c.inventory.goldGp,h.inventory.goldGp,`${label}: GP diverges`);assert.deepEqual(c.inventory.items,h.inventory.items,`${label}: inventory diverges`);}return {actions:h.actions.length,items:h.inventory?.items.length??null,goldGp:h.inventory?.goldGp??null,roster:h.roster.length,availabilityCompared:ownTurn,offTurnAvailability:ownTurn?null:{host:h.actions.filter((a)=>a.available).length,client:c.actions.filter((a)=>a.available).length}};}
async function walkToActor(host,actorId,{fresh=true}={}){const before=await peerState(host);if(before.mode!=="initiative")await hostCall(host,`await mockAdapter.startInitiative();`);else if(fresh&&before.currentActorId===actorId)await hostCall(host,`await mockAdapter.endTurn();`);for(let step=0;step<16;step+=1){const s=await peerState(host);if(s.currentActorId===actorId)return s;await hostCall(host,`await mockAdapter.endTurn();`);}const s=await peerState(host);throw new Error(`Host could not walk the initiative order to ${actorId}; current=${s.currentActorId} entities=${s.entities.map((e)=>e.id).join(",")}`);}
async function hostAdvanceToComplete(host,resolutionId){let last=null;for(let step=0;step<14;step+=1){last=await peerState(host);if(!last.resolution||last.resolution.id!==resolutionId)break;if(last.resolution.stage==="complete")return last;if(!last.resolution.canAdvance){await sleep(300);continue;}await hostCall(host,`await mockAdapter.advanceResolution();`);}last=await peerState(host);return last;}
async function clientAct(client,actionId,targetIds){return client.browser.executeAsync((actionId,targetIds,done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const s=await mockAdapter.resolveAction(actionId,targetIds);await publishConnectedSnapshot(mockAdapter);done({ok:true,resolutionId:s.resolution?.id??null,stage:s.resolution?.stage??null,compatibilityMessage:s.session.compatibilityMessage});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));},actionId,targetIds);}
async function waitHostResolutionFor(host,actorId,timeout=20_000){let last=null;await host.browser.waitUntil(async()=>{last=await peerState(host);return Boolean(last.resolution&&last.resolution.actorId===actorId&&!seenResolutionIds.has(last.resolution.id));},{timeout,interval:200,timeoutMsg:`Host did not start a new Resolution for ${actorId}; last=${JSON.stringify(last?.resolution)} msg=${last?.compatibilityMessage}`});seenResolutionIds.add(last.resolution.id);return last;}
async function waitActivityEntry(instance,resolutionId,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await peerState(instance);return last.activity.some((e)=>e.id===resolutionId);},{timeout,interval:200,timeoutMsg:`${instance.label} did not record ${resolutionId}; activity=${JSON.stringify(last?.activity?.map((e)=>e.id))} msg=${last?.compatibilityMessage}`});return last;}
async function openActivity(instance){const open=await instance.browser.$("aside.session-activity-pane");if(await open.isExisting())return;await click(instance.browser,exactButton("기록"),`${instance.label} 기록 패널`);await instance.browser.$("aside.session-activity-pane").waitForExist({timeout:10_000});}
async function closeActivity(instance){await instance.browser.keys("Escape");await sleep(200);}
async function renderedActivityText(instance){await openActivity(instance);const text=await instance.browser.$("aside.session-activity-pane").getText().catch(async()=>bodyText(instance));return text;}
function d20FaceOf(state,resolutionId){const entry=state.activity.find((e)=>e.id===resolutionId);const detail=(entry?.detail??[]).join("\n");const match=detail.match(/selected d20 (\d+)/);if(match)return Number(match[1]);const dice=state.resolution&&state.resolution.id===resolutionId?state.resolution.dice:[];return dice.length?dice[0]:null;}
function assertQueuedD20(state,resolutionId,face,label){const seen=d20FaceOf(state,resolutionId);assert.equal(seen,face,`${label}: authoritative d20 must be the queued ${face}; Host committed ${seen} (dice=${JSON.stringify(state.resolution?.dice)})`);}
function entity(state,id){return state.entities.find((e)=>e.id===id);}
const terminalView=(r)=>r?{id:r.id,stage:r.stage,actionName:r.actionName,actorId:r.actorId,targetIds:r.targetIds,attackOutcome:r.attackOutcome??null,attackTotal:r.attackTotal??null,rollTotal:r.rollTotal??null,finalOutcome:r.finalOutcome??null,compact:r.compact??null,critical:r.critical??null,checkOutcome:r.checkOutcome??null}:null;
async function waitClientTerminal(client,resolutionId,timeout=30_000){let last=null,announcement="";await client.browser.waitUntil(async()=>{last=await peerState(client);if(last.announcement&&last.announcement.length>announcement.length)announcement=last.announcement;const applied=last.activity.some((e)=>e.id===resolutionId);if(!applied)return false;const r=last.resolution;if(r&&r.id===resolutionId)return r.stage==="complete";return true;},{timeout,interval:200,timeoutMsg:`${client.label} did not reach the terminal presentation of ${resolutionId}; last=${JSON.stringify(last?.resolution)} msg=${last?.compatibilityMessage}`});return{state:last,announcement};}
async function expectConverged(peers,resolutionId,label){const host=await waitActivityEntry(peers[0],resolutionId);const hostEntry=host.activity.find((e)=>e.id===resolutionId);const states=[[peers[0].label,host]];const views=[];const announcements={};const clientEntries=[];for(const p of peers.slice(1)){const {state,announcement}=await waitClientTerminal(p,resolutionId);states.push([p.label,state]);announcements[p.label]=announcement;const e=state.activity.find((x)=>x.id===resolutionId);assert.ok(e,`${label}: ${p.label} has no committed entry`);clientEntries.push([p.label,{title:e.title,summary:e.summary,stateChanges:e.stateChanges}]);for(const he of host.entities){const pe=entity(state,he.id);if(pe)assert.equal(pe.hp,he.hp,`${label}: ${p.label} HP for ${he.name} diverges (${pe.hp} vs Host ${he.hp})`);}if(state.resolution&&state.resolution.id===resolutionId)views.push([p.label,terminalView(state.resolution)]);}for(const [name,entry] of clientEntries.slice(1))assert.deepEqual(entry,clientEntries[0][1],`${label}: ${name} committed entry diverges from ${clientEntries[0][0]}`);if(views.length>=2){for(const [name,view] of views.slice(1))assert.deepEqual(view,views[0][1],`${label}: ${name} terminal resolution view diverges from ${views[0][0]}`);}assert.ok(hostEntry,`${label}: Host has no committed entry`);states.announcements=announcements;states.views=views;return states;}
async function evidenceAll(peers,suffix){for(const p of peers)await bounded(saveEvidence(p,suffix).catch(()=>undefined),15_000,"evidence");}

async function readyConfigurations(instance){return peerCall(instance,`const {readyActionConfigurationsFor}=await import("/src/app/standardActionReadyState.ts");return readyActionConfigurationsFor(mockAdapter);`);}
async function hostConcentration(host){return peerCall(host,`const {snapshotAdapterTurnRuntimeState}=await import("/src/app/turnRuntimeSessionRegistry.ts");const s=await mockAdapter.getSnapshot();const st=snapshotAdapterTurnRuntimeState(mockAdapter,s.scene);return st?{concentration:st.concentration,effects:st.effects.map((e)=>({sourceId:e.sourceId,targetId:e.targetId,tags:e.tags??[]}))}:null;`);}
async function waitStatus(instance,actorId,predicate,description,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await peerState(instance);const e=entity(last,actorId);return Boolean(e)&&predicate(e.status??[]);},{timeout,interval:200,timeoutMsg:`${instance.label} did not observe ${description}; status=${JSON.stringify(entity(last??{entities:[]},actorId)?.status)}`});return last;}
async function waitCursor(instance,cursor,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await peerState(instance);return last.cursor>=cursor;},{timeout,interval:200,timeoutMsg:`${instance.label} did not reach Host cursor ${cursor}; last=${last?.cursor}`});return last;}
async function hostAdvanceUntil(host,resolutionId,predicate,timeout=20_000){const started=Date.now();let last=null;while(Date.now()-started<timeout){last=await peerState(host);if(!last.resolution||last.resolution.id!==resolutionId)return last;if(predicate(last.resolution))return last;if(last.resolution.canAdvance)await hostCall(host,`await mockAdapter.advanceResolution();`);else await sleep(250);}return last;}
// A Ready arm commits a ready-action Host event (not a resolution entry); peers converge by cursor and the 준비 행동 status.
async function syncCursors(host,clients){const cursor=(await peerState(host)).cursor;for(const p of clients)await waitCursor(p,cursor);return cursor;}
async function armReady(host,p2,bard2,dagger,trigger){const armed=await peerCall(p2,`const s=await mockAdapter.configureReadyAction({actorId:args.actorId,actionId:args.actionId,trigger:args.trigger});return {stage:s.resolution?.stage??null,msg:s.session.compatibilityMessage};`,{actorId:bard2.id,actionId:dagger.id,trigger});const hostRes=await waitHostResolutionFor(host,bard2.id);const done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(done.resolution?.stage,"complete",JSON.stringify(done.resolution));return {armed,done};}

async function runScenario(){
  assert.equal(process.platform,"win32","W9-02 Tauri acceptance is Windows-only");assert.ok(existsSync(binary),`Tauri E2E binary was not found: ${binary}`);
  await rm(runRoot,{recursive:true,force:true});await mkdir(artifactRoot,{recursive:true});await ensureVite();
  const sessionPort=await reservePort();const hostRoot=path.join(runRoot,"host","data");const p1Root=path.join(runRoot,"p1","data");const p2Root=path.join(runRoot,"p2","data");
  const host=await launchInstance("W9-02D Host",hostRoot,await reservePort());const p1=await launchInstance("W9-02D P1",p1Root,await reservePort());const p2=await launchInstance("W9-02D P2",p2Root,await reservePort());
  const peers=[host,p1,p2];const scenarios={};const record=(id,data)=>{scenarios[id]={status:"PASS",...data};log(`${id} PASS`);};
  const fighter1=await createDistinctPlayerCharacter(p1,"W9 Fighter One");
  const BARD={className:"바드",spellTiles:{"choice:class.spells.cantrips":["잔혹한 모욕","빛"],"choice:class.spells.prepared":["요정 불꽃","천둥파동","치유의 단어","상처 치료"]},choiceCards:{"choice:class.instrument-proficiencies":"류트","choice:class.loadout.0":"류트"}};
  const bard2=await createDistinctPlayerCharacter(p2,"W9 Bard Two",BARD);
  await createHostCampaign(host);await openHostSession(host,sessionPort);await joinClientSession(p1,sessionPort);await joinClientSession(p2,sessionPort);
  await host.browser.waitUntil(async()=>(await peerState(host)).entities.filter((e)=>e.kind==="character").length>=2,{timeout:20_000,timeoutMsg:"H/P1/P2 Characters did not enter the Host Scene"});
  // Two goblins through the production DM Library path so an area spell has several targets.
  const goblinIds=await hostCall(host,`const initial=await mockAdapter.getSnapshot();const campaign=initial.campaigns?.find((entry)=>entry.name==="W7-05 Hidden Roll")??initial.campaigns?.[0];if(!campaign)throw new Error("W9-02D Campaign was not found");const entry={entryId:"w9.d.goblin",kind:"npc-definition",label:"W9 고블린",definitionId:"local.w9.d.goblin",favorite:false,tags:["W9-02D"],npcDefinition:{definitionId:"local.w9.d.goblin",name:"고블린",nameEn:"Goblin",ac:15,maxHp:21,actions:["시미터","숏보우"],statusImmunities:[],source:"W9-02D",version:"1",runtimeStats:{abilities:{str:8,dex:14,con:10,int:10,wis:8,cha:8},proficiencyBonus:2,savingThrowProficiencies:[],speed:30,resistances:[],immunities:[],vulnerabilities:[]},runtimeActions:[{id:"scimitar",name:"시미터",category:"weapon",sourceKind:"weapon",attackBonus:4,rangeFeet:5,damage:{type:"참격",dice:"1d6",flat:2}},{id:"shortbow",name:"숏보우",category:"weapon",sourceKind:"weapon",attackBonus:4,rangeFeet:80,damage:{type:"관통",dice:"1d6",flat:2}}]}};await mockAdapter.upsertCampaignDmLibraryEntry(campaign.campaignId,entry);await mockAdapter.instantiateCampaignDmLibraryNpcDefinition(campaign.campaignId,entry.entryId);const snapshot=await mockAdapter.instantiateCampaignDmLibraryNpcDefinition(campaign.campaignId,entry.entryId);const ids=snapshot.scene.entities.filter((e)=>e.id.startsWith("local.w9.d.goblin.instance-")).map((e)=>e.id);if(ids.length<2)throw new Error("two goblin NPCs expected; entities="+snapshot.scene.entities.map((e)=>e.id).join(","));return ids;`);
  for(const p of [p1,p2])await p.browser.waitUntil(async()=>{const s=await peerState(p);return goblinIds.every((id)=>Boolean(entity(s,id)));},{timeout:15_000,timeoutMsg:`${p.label} did not receive the NPC topology`});
  await evidenceAll(peers,"w9-02d-setup");
  let hostRes=null;
  try{
    // MP-D01: Start Initiative — the authoritative order and current Actor converge on every peer.
    assert.notEqual((await peerState(host)).mode,"initiative","the Session must start outside Initiative");
    await hostCall(host,`await mockAdapter.startInitiative();`);
    for(const p of [p1,p2])await p.browser.waitUntil(async()=>(await peerState(p)).mode==="initiative",{timeout:15_000,timeoutMsg:`${p.label} did not enter Initiative`});
    const d01Host=await peerState(host);const order=(s)=>s.entities.map((e)=>[e.id,e.initiative]).sort((a,b)=>a[0]<b[0]?-1:1);
    for(const p of [p1,p2]){await p.browser.waitUntil(async()=>(await peerState(p)).currentActorId===d01Host.currentActorId,{timeout:15_000,timeoutMsg:`${p.label} current Actor diverges after Start Initiative`});const s=await peerState(p);assert.deepEqual(order(s),order(d01Host),`${p.label} initiative order diverges`);}
    await evidenceAll(peers,"w9-02d-d01");record("MP-D01",{currentActorId:d01Host.currentActorId,order:order(d01Host)});

    // MP-D02: the DM ends the turn; the next Actor and its fresh economy converge.
    const d02Before=(await peerState(host)).currentActorId;await hostCall(host,`await mockAdapter.endTurn();`);
    const d02Host=await peerState(host);assert.notEqual(d02Host.currentActorId,d02Before,"end turn must advance the current Actor");
    for(const p of [p1,p2])await p.browser.waitUntil(async()=>(await peerState(p)).currentActorId===d02Host.currentActorId,{timeout:15_000,timeoutMsg:`${p.label} did not follow the turn advance`});
    record("MP-D02",{from:d02Before,to:d02Host.currentActorId});

    // MP-D03: an off-turn Character intent is refused with an explicit reason and nothing is committed.
    const offInstance=d02Host.currentActorId===fighter1.id?p2:p1;const offActor=d02Host.currentActorId===fighter1.id?bard2:fighter1;
    // Availability is re-projected on the Client after the turn event lands; wait for the projection rather than the first snapshot.
    let offAction=null;await offInstance.browser.waitUntil(async()=>{const list=await actions(offInstance,offActor.id);offAction=list.find((a)=>a.resolutionKind==="attack"&&!a.readyActionRole)??null;return Boolean(offAction)&&offAction.available===false;},{timeout:15_000,interval:300,timeoutMsg:`${offInstance.label}: off-turn attack stayed available; ${JSON.stringify(offAction)}`});
    assert.ok(offAction.disabledReason,"disabled reason must be explicit");
    const cursorD03=(await peerState(host)).cursor;const d03=await clientAct(offInstance,offAction.id,[goblinIds[0]]);await sleep(1500);
    const afterD03=await peerState(host);assert.equal(afterD03.cursor,cursorD03,"off-turn intent must not commit");assert.equal(afterD03.pendingRemote,false);
    record("MP-D03",{actor:offActor.id,disabledReason:offAction.disabledReason,clientMessage:d03.compatibilityMessage});

    // MP-D08: P2 arms Ready on its own turn; configuration, economy, and the 준비 행동 status fan out; the Host holds the configuration.
    await walkToActor(host,bard2.id);
    const dagger=await findAction(p2,bard2.id,(a)=>/단검|dagger/i.test(a.name)&&a.available&&!a.readyActionRole,"bard dagger attack");
    const d08=await armReady(host,p2,bard2,dagger,"고블린이 접근하면");
    await syncCursors(host,[p1,p2]);
    for(const p of peers)await waitStatus(p,bard2.id,(status)=>status.includes("준비 행동"),"Ready status");
    const hostReady=await readyConfigurations(host);assert.ok(hostReady.some((c)=>c.actorId===bard2.id&&c.actionId===dagger.id),`Host must hold the Ready configuration; got ${JSON.stringify(hostReady)}`);
    const d08Economy=entity(await peerState(host),bard2.id);
    await evidenceAll(peers,"w9-02d-d08");record("MP-D08",{resolutionId:d08.done.resolution.id,hostReady,armed:d08.armed});

    // MP-D09: on the goblin's turn P2 fires the readied attack as a reaction; H resolves it, presentation is shared, Ready clears exactly once.
    await walkToActor(host,goblinIds[0]);
    const trigger=await findAction(p2,bard2.id,(a)=>a.readyActionRole==="trigger"&&a.available,"ready trigger");
    await hostCall(host,`await mockAdapter.setQueuedD20(15);`);
    const d09=await clientAct(p2,trigger.id,[goblinIds[0]]);assert.equal(d09.ok,true,d09.error);
    hostRes=await waitHostResolutionFor(host,bard2.id);const d09Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(d09Done.resolution?.stage,"complete",JSON.stringify(d09Done.resolution));
    const d09States=await expectConverged(peers,d09Done.resolution.id,"MP-D09");
    for(const p of peers)await waitStatus(p,bard2.id,(status)=>!status.includes("준비 행동"),"Ready cleared after trigger");
    assert.deepEqual((await readyConfigurations(host)).filter((c)=>c.actorId===bard2.id),[],"Host must clear the Ready configuration once the trigger fires");
    assert.deepEqual((await readyConfigurations(p2)).filter((c)=>c.actorId===bard2.id),[],"owner must clear its local Ready configuration");
    await evidenceAll(peers,"w9-02d-d09");record("MP-D09",{resolutionId:d09Done.resolution.id,outcome:d09Done.resolution.attackOutcome,d20:d20FaceOf(d09Done,d09Done.resolution.id),clientViews:d09States.views});

    // MP-D10: Ready armed, then cleared at P2's next own turn — the turn event precedes the actor-specific clear.
    await walkToActor(host,bard2.id);const d10=await armReady(host,p2,bard2,dagger,"다음 턴까지 대기");await syncCursors(host,[p1,p2]);
    for(const p of peers)await waitStatus(p,bard2.id,(status)=>status.includes("준비 행동"),"Ready status (D10)");
    const cursorD10=(await peerState(host)).cursor;await walkToActor(host,bard2.id);
    for(const p of peers)await waitStatus(p,bard2.id,(status)=>!status.includes("준비 행동"),"Ready cleared at the next own turn");
    assert.deepEqual((await readyConfigurations(host)).filter((c)=>c.actorId===bard2.id),[],"Host must clear the Ready configuration at the actor's next turn");
    const d10Host=await peerState(host);for(const p of [p1,p2])await waitCursor(p,d10Host.cursor);
    await evidenceAll(peers,"w9-02d-d10");record("MP-D10",{armResolutionId:d10.done.resolution.id,cursorBefore:cursorD10,cursorAfter:d10Host.cursor});

    // MP-D11: Ready armed, then Initiative ends — every peer clears deterministically; no stale configuration survives.
    const d11=await armReady(host,p2,bard2,dagger,"전투 종료까지");await syncCursors(host,[p1,p2]);
    for(const p of peers)await waitStatus(p,bard2.id,(status)=>status.includes("준비 행동"),"Ready status (D11)");
    await hostCall(host,`await mockAdapter.endInitiative();`);
    for(const p of [p1,p2])await p.browser.waitUntil(async()=>(await peerState(p)).mode!=="initiative",{timeout:15_000,timeoutMsg:`${p.label} did not leave Initiative`});
    for(const p of peers)await waitStatus(p,bard2.id,(status)=>!status.includes("준비 행동"),"Ready cleared when Initiative ends");
    assert.deepEqual(await readyConfigurations(host),[],"no Ready configuration may survive the end of Initiative on the Host");assert.deepEqual(await readyConfigurations(p2),[],"no Ready configuration may survive on the owner");
    await evidenceAll(peers,"w9-02d-d11");record("MP-D11",{armResolutionId:d11.done.resolution.id});
    await hostCall(host,`await mockAdapter.startInitiative();`);for(const p of [p1,p2])await p.browser.waitUntil(async()=>(await peerState(p)).mode==="initiative",{timeout:15_000,timeoutMsg:`${p.label} did not re-enter Initiative`});

    // MP-D04 + MP-D05: Bardic Inspiration on P1, then P1's miss offers the private follow-up only to P1; P1 accepts and the original resolution resumes with the authoritative result.
    await walkToActor(host,bard2.id);
    const inspire=await findAction(p2,bard2.id,(a)=>a.id==="action.bard.bardic-inspiration"&&a.available,"Bardic Inspiration");
    const ins1=await clientAct(p2,inspire.id,[fighter1.id]);assert.equal(ins1.ok,true,ins1.error);
    hostRes=await waitHostResolutionFor(host,bard2.id);const ins1Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(ins1Done.resolution?.stage,"complete",JSON.stringify(ins1Done.resolution));await expectConverged(peers,ins1Done.resolution.id,"MP-D04 inspiration");
    const effectsAfterInspire=await hostConcentration(host);assert.ok(effectsAfterInspire?.effects.some((e)=>e.targetId===fighter1.id),`inspiration effect must sit on P1's Character in the Host runtime; got ${JSON.stringify(effectsAfterInspire)}`);
    await walkToActor(host,fighter1.id);await hostCall(host,`await mockAdapter.setQueuedD20(2);`);
    const greatsword=await findAction(p1,fighter1.id,(a)=>a.name.startsWith("대검")&&a.available,"greatsword attack");
    const d04=await clientAct(p1,greatsword.id,[goblinIds[0]]);assert.equal(d04.ok,true,d04.error);
    hostRes=await waitHostResolutionFor(host,fighter1.id);
    const d04Host=await hostAdvanceUntil(host,hostRes.resolution.id,(r)=>r.stage==="interrupt");
    assert.equal(d04Host.resolution?.stage,"interrupt",`the miss must open the follow-up interrupt on the Host; got ${JSON.stringify(d04Host.resolution)}`);
    assert.equal(d04Host.resolution.interrupt?.responderId,fighter1.id,JSON.stringify(d04Host.resolution.interrupt));
    let p1Prompt=null;await p1.browser.waitUntil(async()=>{p1Prompt=(await peerState(p1)).resolution?.interrupt??null;return Boolean(p1Prompt);},{timeout:15_000,timeoutMsg:"P1 did not receive the private interrupt prompt"});
    assert.equal(p1Prompt.responderId,fighter1.id);
    const p2Public=await peerState(p2);assert.equal(p2Public.resolution?.interrupt??null,null,"the observer must not receive the private prompt");
    assert.equal(JSON.stringify(p2Public.resolution).includes(p1Prompt.optionName),false,"public waiting state must not reveal the private option");
    await evidenceAll(peers,"w9-02d-d04");record("MP-D04",{resolutionId:hostRes.resolution.id,prompt:p1Prompt,publicCompact:p2Public.resolution?.compact??null});
    const accepted=await peerCall(p1,`const s=await mockAdapter.respondToInterrupt(true);return {stage:s.resolution?.stage??null,msg:s.session.compatibilityMessage};`);
    await host.browser.waitUntil(async()=>{const s=await peerState(host);return s.resolution?.id===hostRes.resolution.id&&s.resolution.stage!=="interrupt";},{timeout:15_000,timeoutMsg:"Host did not resume after the owner's accepted reaction"});
    const d05Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(d05Done.resolution?.stage,"complete",JSON.stringify(d05Done.resolution));
    const d05States=await expectConverged(peers,d05Done.resolution.id,"MP-D05");
    await evidenceAll(peers,"w9-02d-d05");record("MP-D05",{resolutionId:d05Done.resolution.id,accepted,outcome:d05Done.resolution.attackOutcome,attackTotal:d05Done.resolution.attackTotal,detail:(d05Done.activity.find((e)=>e.id===d05Done.resolution.id)?.detail??[]).filter((line)=>/영감|bonus|d20/.test(line)).slice(0,4),clientViews:d05States.views});

    // MP-D06: a second inspiration, another miss; the Host's authoritative timeout declines the private prompt once and public play resumes.
    await walkToActor(host,bard2.id);
    const inspire2=await findAction(p2,bard2.id,(a)=>a.id==="action.bard.bardic-inspiration"&&a.available,"Bardic Inspiration (2)");
    const ins2=await clientAct(p2,inspire2.id,[fighter1.id]);assert.equal(ins2.ok,true,ins2.error);
    hostRes=await waitHostResolutionFor(host,bard2.id);const ins2Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(ins2Done.resolution?.stage,"complete",JSON.stringify(ins2Done.resolution));await expectConverged(peers,ins2Done.resolution.id,"MP-D06 inspiration");
    await walkToActor(host,fighter1.id);await hostCall(host,`await mockAdapter.setQueuedD20(1);`);
    const d06=await clientAct(p1,greatsword.id,[goblinIds[0]]);assert.equal(d06.ok,true,d06.error);
    hostRes=await waitHostResolutionFor(host,fighter1.id);
    const d06Host=await hostAdvanceUntil(host,hostRes.resolution.id,(r)=>r.stage==="interrupt");assert.equal(d06Host.resolution?.stage,"interrupt",JSON.stringify(d06Host.resolution));
    await p1.browser.waitUntil(async()=>Boolean((await peerState(p1)).resolution?.interrupt),{timeout:15_000,timeoutMsg:"P1 did not receive the second private prompt"});
    const expired=await host.browser.executeAsync((resolutionId,done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedActionRoutingAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{expireConnectedInterrupt},{publishConnectedSnapshot}])=>{const result=await expireConnectedInterrupt(mockAdapter,resolutionId);await publishConnectedSnapshot(mockAdapter);done({ok:true,result:String(result)});}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));},hostRes.resolution.id);assert.equal(expired.ok,true,expired.error);
    const d06Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(d06Done.resolution?.stage,"complete",JSON.stringify(d06Done.resolution));
    assert.equal(d06Done.resolution.attackOutcome,"빗나감","a declined follow-up must leave the miss in place");
    const d06States=await expectConverged(peers,d06Done.resolution.id,"MP-D06");
    await p1.browser.waitUntil(async()=>!(await peerState(p1)).resolution?.interrupt,{timeout:15_000,timeoutMsg:"P1's private prompt must be withdrawn once the Host declines it"});
    await evidenceAll(peers,"w9-02d-d06");record("MP-D06",{resolutionId:d06Done.resolution.id,expired,outcome:d06Done.resolution.attackOutcome,clientViews:d06States.views});

    // MP-C14: Thunderwave — an area/multi-target save spell in mapless Core: two targets, two saves, one shared presentation.
    await walkToActor(host,bard2.id);
    const wave=await findAction(p2,bard2.id,(a)=>a.spellId==="dnd.srd521.spell.thunderwave"&&a.available,"Thunderwave");
    const c14=await clientAct(p2,wave.id,goblinIds);assert.equal(c14.ok,true,c14.error);
    hostRes=await waitHostResolutionFor(host,bard2.id);const c14Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(c14Done.resolution?.stage,"complete",JSON.stringify(c14Done.resolution));
    assert.equal(c14Done.resolution.saves.length,2,`two targets must each roll a save; got ${JSON.stringify(c14Done.resolution.saves)}`);
    const c14States=await expectConverged(peers,c14Done.resolution.id,"MP-C14");
    await evidenceAll(peers,"w9-02d-c14");record("MP-C14",{resolutionId:c14Done.resolution.id,saves:c14Done.resolution.saves,clientViews:c14States.views});

    // MP-D07: Faerie Fire holds concentration; the goblin's hit forces the owner's private concentration save; the owner answers and the public state follows in order.
    await walkToActor(host,bard2.id);
    const faerie=await findAction(p2,bard2.id,(a)=>a.spellId==="dnd.srd521.spell.faerie-fire"&&a.available,"Faerie Fire");
    const ff=await clientAct(p2,faerie.id,[goblinIds[1]]);assert.equal(ff.ok,true,ff.error);
    hostRes=await waitHostResolutionFor(host,bard2.id);const ffDone=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(ffDone.resolution?.stage,"complete",JSON.stringify(ffDone.resolution));await expectConverged(peers,ffDone.resolution.id,"MP-D07 cast");
    const concBefore=await hostConcentration(host);assert.ok(concBefore?.concentration?.[bard2.id],`Host runtime must hold the bard's concentration; got ${JSON.stringify(concBefore)}`);
    await walkToActor(host,goblinIds[0]);
    const scimitar=await findAction(host,goblinIds[0],(a)=>/시미터|Scimitar/i.test(a.name),"goblin scimitar");
    await hostCall(host,`await mockAdapter.selectDmActor(args.goblinId);await mockAdapter.setQueuedD20(19);await mockAdapter.resolveAction(args.actionId,[args.targetId]);`,{goblinId:goblinIds[0],actionId:scimitar.id,targetId:bard2.id});
    hostRes=await waitHostResolutionFor(host,goblinIds[0]);
    const d07Host=await hostAdvanceUntil(host,hostRes.resolution.id,(r)=>Boolean(r.concentrationSave));
    assert.ok(d07Host.resolution?.concentrationSave,`the hit must request a concentration save on the Host; got ${JSON.stringify(d07Host.resolution)}`);assert.equal(d07Host.resolution.concentrationSave.targetId,bard2.id);
    await p2.browser.waitUntil(async()=>Boolean((await peerState(p2)).resolution?.concentrationSave),{timeout:15_000,timeoutMsg:"the owner did not receive the private concentration save"});
    assert.equal((await peerState(p1)).resolution?.concentrationSave??null,null,"a non-owner must not receive the private concentration save");
    const submitted=await peerCall(p2,`const s=await mockAdapter.submitConcentrationSaveD20(3);return {compact:s.resolution?.compact??null,msg:s.session.compatibilityMessage};`);
    await host.browser.waitUntil(async()=>{const s=await peerState(host);return s.resolution?.id===hostRes.resolution.id&&s.resolution.concentrationSave?.natural===3;},{timeout:15_000,timeoutMsg:"Host did not receive the owner's concentration d20"});
    const d07Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(d07Done.resolution?.stage,"complete",JSON.stringify(d07Done.resolution));
    const d07States=await expectConverged(peers,d07Done.resolution.id,"MP-D07");
    const concAfter=await hostConcentration(host);assert.equal(concAfter?.concentration?.[bard2.id]??null,null,`a failed save must end concentration; got ${JSON.stringify(concAfter?.concentration)}`);
    await evidenceAll(peers,"w9-02d-d07");record("MP-D07",{resolutionId:d07Done.resolution.id,save:d07Done.resolution.concentrationSave,submitted,clientViews:d07States.views});

    // MP-D12: DM undo — a compensating event returns HP on every peer while the original entry stays in history.
    const undoId=d07Done.resolution.id;const bardHpBeforeUndo=entity(await peerState(host),bard2.id).hp;const cursorD12=(await peerState(host)).cursor;
    await hostCall(host,`await mockAdapter.undoLastResolution();`);
    const d12Host=await peerState(host);assert.ok(d12Host.cursor>cursorD12,"undo must commit a compensating event");
    const bardHpAfterUndo=entity(d12Host,bard2.id).hp;assert.ok(bardHpAfterUndo>bardHpBeforeUndo,`undo must restore the goblin's damage (${bardHpBeforeUndo} -> ${bardHpAfterUndo})`);
    for(const p of [p1,p2]){const s=await waitCursor(p,d12Host.cursor);assert.equal(entity(s,bard2.id).hp,bardHpAfterUndo,`${p.label} HP diverges after undo`);assert.ok(s.activity.some((e)=>e.id===undoId),`${p.label} must keep the original entry in history`);}
    await evidenceAll(peers,"w9-02d-d12");record("MP-D12",{undone:undoId,hpBefore:bardHpBeforeUndo,hpAfter:bardHpAfterUndo,cursorBefore:cursorD12,cursorAfter:d12Host.cursor,hostTop:d12Host.activity.slice(0,2).map((e)=>e.title)});

    // MP-D13: a DM correction after presentation is a new event; the already shown dice of the original stay untouched on every peer.
    await walkToActor(host,fighter1.id);await hostCall(host,`await mockAdapter.setQueuedD20(12);`);
    const d13=await clientAct(p1,greatsword.id,[goblinIds[0]]);assert.equal(d13.ok,true,d13.error);
    hostRes=await waitHostResolutionFor(host,fighter1.id);const d13Done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(d13Done.resolution?.stage,"complete",JSON.stringify(d13Done.resolution));
    await expectConverged(peers,d13Done.resolution.id,"MP-D13 original");
    const originalEntries={};for(const p of [p1,p2]){const e=(await peerState(p)).activity.find((x)=>x.id===d13Done.resolution.id);originalEntries[p.label]={detail:e.detail,stateChanges:e.stateChanges};}
    const cursorD13=(await peerState(host)).cursor;
    await hostCall(host,`await mockAdapter.applyDmAdjudication({type:"modifier",value:5,scope:"resolution",reason:"W9-02D correction"});`);
    const d13Host=await peerState(host);assert.ok(d13Host.cursor>cursorD13,`the correction must commit a new event; msg=${d13Host.compatibilityMessage}`);
    for(const p of [p1,p2]){const s=await waitCursor(p,d13Host.cursor);const e=s.activity.find((x)=>x.id===d13Done.resolution.id);assert.deepEqual({detail:e.detail,stateChanges:e.stateChanges},originalEntries[p.label],`${p.label} must not rewrite the original entry`);assert.notEqual(s.activity[0].id,d13Done.resolution.id,`${p.label} must record the correction as a newer entry`);}
    await evidenceAll(peers,"w9-02d-d13");record("MP-D13",{resolutionId:d13Done.resolution.id,cursorBefore:cursorD13,cursorAfter:d13Host.cursor,hostTop:d13Host.activity[0]?.title??null});
  }catch(error){await evidenceAll(peers,"w9-02d-failure");const diag={};for(const p of peers)diag[p.label]=await bounded(peerState(p).catch((e)=>({error:String(e)})),8_000,"state");await writeFile(path.join(artifactRoot,"w9-02d-failure-state.json"),`${JSON.stringify({scenarios,diag},null,2)}\n`,"utf8").catch(()=>undefined);throw new Error(`${error instanceof Error?error.message:String(error)}; passed=${Object.keys(scenarios).join(",")} states=${JSON.stringify(diag).slice(0,3000)}`);}
  const evidence={gate:"W9-02",family:"D",scope:Object.keys(scenarios),status:"PASS",verificationSha,windowsTauri:true,topology:{host:"DM Host",clients:["P1 Fighter","P2 Bard"],npcs:goblinIds,sessionPort},scenarios};
  await writeFile(path.join(artifactRoot,"w9-02d-summary.json"),`${JSON.stringify(evidence,null,2)}\n`,"utf8");log(`PASS evidence: ${path.join(artifactRoot,"w9-02d-summary.json")}`);
}

async function cleanup(){if(keepOpen){log(`--keep-open active. Evidence: ${artifactRoot}`);return;}for(const browser of [...browsers].reverse()){try{await browser.deleteSession();}catch{}}for(const child of [...children].reverse()){if(child.exitCode===null&&!child.killed){try{child.kill();}catch{}}}if(viteStarted)log("Vite process stopped with tracked child cleanup.");}

let exitCode=0;try{await runScenario();}catch(error){exitCode=1;console.error(error instanceof Error?error.stack??error.message:error);try{await writeFile(path.join(artifactRoot,"w9-02d-failure.txt"),`${String(error instanceof Error?error.stack??error.message:error)}\n`,"utf8");}catch{}}finally{await cleanup();}process.exitCode=exitCode;
